[{"fieldname": "print_heading_template", "fieldtype": "Custom HTML", "options": "{% set company = frappe.get_doc("Company", doc.company) if doc.company else None %}
{% macro addr_block(address_name) -%}
  {%- if address_name -%}
    {%- set a = frappe.get_doc("Address", address_name) -%}
    <div class="addr">
      <div class="strong">{{ a.address_title or "" }}</div>
      {% if a.address_line1 %}
        <div>{{ a.address_line1 }}</div>
      {% endif %}
      {% if a.address_line2 %}
        <div>{{ a.address_line2 }}</div>
      {% endif %}
      <div>
        {{ a.city or "" }}{% if a.city and a.state %}, {% endif %}{{ a.state or "" }}
        {% if a.pincode %} {{ a.pincode }}{% endif %}
      </div>
      {% if a.country %}
        <div>{{ a.country }}</div>
      {% endif %}
      {% if a.phone %}
        <div>Phone: {{ a.phone }}</div>
      {% endif %}
      {% if a.mobile_no %}
        <div>Mobile Phone: {{ a.mobile_no }}</div>
      {% endif %}
    </div>
  {%- else -%}
    <div class="muted">—</div>
  {%- endif -%}
{%- endmacro %}

{% set email_addr = doc.contact_email %}
{% if not email_addr and doc.contact_person %}
  {% set c = frappe.get_doc("Contact", doc.contact_person) %}
  {% set email_addr = c.email_id %}
{% endif %}

{# ===================== Sales Rep Phone + Email from Employee ===================== #}
{% set sales_rep_email = "" %}
{% set sales_rep_phone = "" %}
{% if doc.sales_team and doc.sales_team|length %}
  {% set sp_name = doc.sales_team[0].sales_person %}
  {% set emp_name = frappe.db.get_value("Employee", {"employee_name": sp_name}, "name") %}
  {% if emp_name %}
    {% set emp = frappe.get_doc("Employee", emp_name) %}
    {% set sales_rep_email = emp.user_id or emp.company_email or emp.personal_email or "" %}
    {% set sales_rep_phone = emp.mobile or emp.cell_number or emp.phone_number or "" %}
  {% endif %}
{% endif %}
{# =================================================================================== #}

<style>
  .pf-header * {
    box-sizing: border-box;
  }
  .pf-header {
    width: 100% !important;
    max-width: 100% !important;
    margin: 0 !important;
    padding: 0 !important;
    font-family: Arial, sans-serif !important;
    color: #111 !important;
    font-size: 12px !important;
    line-height: 1.25 !important;
  }
  .pf-header .page {
    width: 100% !important;
    max-width: 100% !important;
    margin: 0 auto !important;
    padding: 0 6px !important;
  }

  .pf-header .brand {
    display: flex !important;
    align-items: center !important;
    gap: 14px !important;
    margin: 10px 0 10px 0 !important;
  }
  .pf-header .logo {
    max-height: 60px !important;
    max-width: 190px !important;
  }
  .pf-header .cname {
    font-size: 32px !important;
    font-weight: 700 !important;
    line-height: 1.05 !important;
  }
  .pf-header .ctag {
    font-size: 11px !important;
    font-weight: 700 !important;
    margin-top: 2px !important;
    letter-spacing: 0.03em !important;
  }

  .pf-header .grid {
    display: grid !important;
    grid-template-columns: 28% 28% 28% !important;
    align-items: start !important;
  }
  .pf-header .title {
    font-weight: 700 !important;
    font-size: 13px !important;
    margin: 0 0 3px 0 !important;
  }
  .pf-header .addr div {
    margin: 1px 0 !important;
  }
  .pf-header .strong {
    font-weight: 700 !important;
  }
  .pf-header .muted {
    color: #666 !important;
  }

  .pf-header .meta table {
    width: 100% !important;
    border-collapse: collapse !important;
  }
  .pf-header .meta td {
    padding: 1px 0 !important;
    vertical-align: top !important;
  }
  .pf-header .meta td.label {
    width: 110px !important;
    font-weight: 700 !important;
  }
  .pf-header .meta td.colon {
    width: 12px !important;
    text-align: center !important;
  }
  .pf-header .meta td.val {
    white-space: nowrap !important;
  }

  .pf-header .email {
    margin-top: 14px !important;
    font-size: 13px !important;
  }
  .pf-header .email .lbltxt {
    font-weight: 700 !important;
  }
  .pf-header .email a {
    color: #0b5ed7 !important;
    text-decoration: underline !important;
  }
</style>

<div class="pf-header">
  <div class="page">
    {# Removed the top line block containing {{ doc.doctype }} #}

    <div class="brand">
      {% if company and company.company_logo %}
        <img class="logo" src="{{ company.company_logo }}" />
      {% endif %}
      <div>
        <div class="cname">
          {{ company.company_name if company else (doc.company or "") }}
        </div>
        <div class="ctag">
          {{ company.company_description if company and company.company_description else "GENERAL MERCHANDISE" }}
        </div>
      </div>
    </div>

    <div class="grid">
      <div>
        <div class="title">Billing Information:</div>
        {{ addr_block(doc.customer_address) }}
      </div>

      <div>
        <div class="title">Shipping Information:</div>
        {{ addr_block(doc.shipping_address_name) }}
      </div>

      <div class="meta">
        <table>
          <tr>
            <td class="label">Order #</td>
            <td class="colon">:</td>
            <td class="val strong">{{ doc.name }}</td>
          </tr>
          <tr>
            <td class="label">Order Date</td>
            <td class="colon">:</td>
            <td class="val">
              {{ frappe.utils.formatdate(doc.posting_date or doc.transaction_date) }}
            </td>
          </tr>
          <tr>
            <td class="label">Sales Rep</td>
            <td class="colon">:</td>
            <td class="val">
              {% if doc.sales_team and doc.sales_team|length %}
                {{ doc.sales_team[0].sales_person }}
              {% else %}—{% endif %}
            </td>
          </tr>
          <tr>
            <td class="label">Sales Rep Phone</td>
            <td class="colon">:</td>
            <td class="val">
              {{ sales_rep_phone or doc.get("sales_rep_phone") or "—" }}
            </td>
          </tr>
          <tr>
            <td class="label">Sales Rep Email</td>
            <td class="colon">:</td>
            <td class="val">
              {{ sales_rep_email or doc.get("sales_rep_email") or "—" }}
            </td>
          </tr>
          <tr>
            <td class="label">Processed By</td>
            <td class="colon">:</td>
            <td class="val">
              {% if doc.sales_team and doc.sales_team|length %}
                {{ doc.sales_team[0].sales_person }}
              {% else %} — {% endif %}
            </td>
          </tr>
          <tr>
            <td class="label">Account #</td>
            <td class="colon">:</td>
            <td class="val">
              {{ doc.get("customer_account_number") or doc.get("account_no") or "—" }}
            </td>
          </tr>
          <tr>
            <td class="label">Status</td>
            <td class="colon">:</td>
            <td class="val">{{ doc.status or "—" }}</td>
          </tr>
          <tr>
            <td class="label">Order Type</td>
            <td class="colon">:</td>
            <td class="val">{{ doc.get("order_type") or "—" }}</td>
          </tr>
        </table>
      </div>
    </div>

    <div class="email">
      <span class="lbltxt">Email Address:</span>
      {% if doc.custom_customer_email %}
        <a href="mailto:{{ doc.custom_customer_email }}">{{ doc.custom_customer_email }}</a>
      {% else %}
        <span class="muted">—</span>
      {% endif %}
    </div>

  </div>
</div>"}, {"fieldtype": "Section Break", "label": ""}, {"fieldtype": "Column Break"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "
{% macro money(val) -%}
  {{ frappe.utils.fmt_money(val or 0, currency=doc.currency) }}
{%- endmacro %}

{# optional: detect shipping/handling rows from taxes table #}
{% set shipping_amt = 0 %}
{% set handling_amt = 0 %}
{% if doc.taxes %}
  {% for t in doc.taxes %}
    {% set x = ((t.description or t.account_head or "")|lower) %}
    {% if "shipping" in x or "pickup" in x %}
      {% set shipping_amt = shipping_amt + (t.tax_amount or 0) %}
    {% elif "handling" in x %}
      {% set handling_amt = handling_amt + (t.tax_amount or 0) %}
    {% endif %}
  {% endfor %}
{% endif %}

<style>
  /* Reserve space for FIXED header + footer (adjust if needed) */
  /*.content{*/
    /*padding-top:170px;   */
    /*padding-bottom:50px; */
  /*  font-family: Arial, sans-serif;*/
  /*  font-size:12px;*/
  /*  color:#111;*/
  /*  line-height:1.25;*/
  /*}*/

  table.items{width:100%; border-collapse:collapse; margin-top:10px;}
  thead{display:table-header-group;} /* repeats on each page */
  tr{page-break-inside:avoid;}
  th,td{padding:6px 6px; vertical-align:top;}
  th{font-weight:700; color:#777; border-bottom:1px solid #bbb;}
  td{border-bottom:1px solid #eee;}

  .center{text-align:center;}
  .num{text-align:right; white-space:nowrap;}
  .sku{font-weight:700; margin-top:4px;}
  .pname{font-weight:700;}
  .muted{color:#666;}
  .img{width:44px; height:44px; border:1px solid #ddd; object-fit:contain;}

  .totals-wrap{margin-top:14px; display:flex; justify-content:flex-end;}
  .totals{min-width:340px;}
  .totals .line{display:flex; justify-content:flex-end; gap:16px; margin:3px 0;}
  .totals .name{min-width:190px; text-align:right;}
  .totals .val{min-width:120px; text-align:right;}
  .totals .grand{font-weight:700; margin-top:6px;}

  .pm{margin-top:14px; border-top:1px solid #bbb; padding-top:8px;}
  .pm .lbltxt{font-weight:700;}
</style>

<div class="content">

  <!-- Items table -->
  <table class="items">
    <thead>
      <tr>
        <th class="center" style="width:60px;">Line#</th>
        <th style="width:90px;">Sku</th>
        <th>Product Name</th>
        <th class="center" style="width:90px;">Case<br>Pack</th>
        <th class="center" style="width:90px;">Quantity</th>
        <th class="center" style="width:90px;">Packing</th>
        <th class="num" style="width:95px;">Price</th>
        <th class="num" style="width:95px;">Total</th>
      </tr>
    </thead>

    <tbody>
      {% for it in doc.items %}
      <tr>
        <td class="center">{{ loop.index }}</td>

        <td>
          {% if it.image %}
            <img class="img" src="{{ it.image }}">
          {% endif %}
          <div class="sku">{{ it.item_code }}</div>
        </td>

        <td>
          <div class="pname">{{ it.item_name or it.item_code  }}</div>
          <!--{% if it.description %}<div class="muted">{{ it.description }}</div>{% endif %}-->
        </td>

        <td class="center">
          {{ it.get("custom_case_pack") or "" }}
        </td>


        <td class="center">{{ it.qty or 0 }}</td>

        <td class="center">
          {{ it.get("packing") or it.get("pack_uom") or it.uom or "" }}
        </td>

        <td class="num">{{ money(it.rate) }}</td>
        <td class="num">{{ money(it.amount) }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <!-- Totals -->
  <div class="totals-wrap">
    <div class="totals">
      <div class="line">
        <div class="name">Subtotal:</div>
        <div class="val">{{ money(doc.total) }}</div>
      </div>

      <div class="line">
        <div class="name">Tax:</div>
        <div class="val">{{ money(doc.total_taxes_and_charges) }}</div>
      </div>

      {% if shipping_amt %}
      <div class="line">
        <div class="name">Shipping (Pickup):</div>
        <div class="val">{{ money(shipping_amt) }}</div>
      </div>
      {% endif %}

      {% if handling_amt %}
      <div class="line">
        <div class="name">Handling:</div>
        <div class="val">{{ money(handling_amt) }}</div>
      </div>
      {% endif %}

      <div class="line grand">
        <div class="name">Grand Total:</div>
        <div class="val">{{ money(doc.grand_total) }}</div>
      </div>

      {% if doc.advance_paid %}
      <div class="line">
        <div class="name">Balance:</div>
        <div class="val">{{ money(doc.outstanding_amount) }}</div>
      </div>
      {% endif %}
    </div>
  </div>

  <!-- Payment Method -->
  <div class="pm">
    <span class="lbltxt">Payment Method:</span>
    <span>{{ doc.custom_mode_of_payment or doc.payment_terms_template or "—" }}</span>
  </div>

</div>
"}, {"fieldtype": "Section Break", "label": ""}, {"fieldtype": "Column Break"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "{# ===================== FOOTER (fixed) ===================== #}

